-- cupel-core: generated by `python -m tools.d1_tables schema`; change Supabase, not this.

CREATE TABLE IF NOT EXISTS "concall_feed" (
    "market" TEXT NOT NULL,
    "symbol" TEXT NOT NULL,
    "quarter" TEXT NOT NULL,
    "company" TEXT,
    "call_date" TEXT NOT NULL,
    "source" TEXT NOT NULL,
    "tone_score" REAL,
    "tone_percentile" REAL,
    "guidance_direction" TEXT,
    "outlook_score" REAL,
    "highlights" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    "management_stance" TEXT,
    "management_stance_quote" TEXT,
    "outlook_detail" TEXT,
    "stored_at" TEXT,
    PRIMARY KEY ("market", "symbol", "quarter")
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS "financial_statements" (
    "market" TEXT NOT NULL DEFAULT 'NSE',
    "symbol" TEXT NOT NULL,
    "statements" TEXT NOT NULL,
    "has_data" INTEGER NOT NULL DEFAULT 0,
    "currency" TEXT NOT NULL,
    "source" TEXT NOT NULL,
    "latest_annual" TEXT,
    "latest_quarter" TEXT,
    "fetched_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    PRIMARY KEY ("market", "symbol")
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS "market_breadth" (
    "market" TEXT NOT NULL DEFAULT 'NSE',
    "scope" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "parent" TEXT,
    "members" INTEGER,
    "position" INTEGER,
    "points" INTEGER NOT NULL,
    "first_session" TEXT NOT NULL,
    "last_session" TEXT NOT NULL,
    "sessions" TEXT NOT NULL,
    "series" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    PRIMARY KEY ("market", "scope", "name")
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS "market_events" (
    "id" INTEGER NOT NULL,
    "market" TEXT NOT NULL,
    "symbol" TEXT NOT NULL,
    "company" TEXT,
    "kind" TEXT NOT NULL,
    "event_key" TEXT NOT NULL,
    "occurred_at" TEXT NOT NULL,
    "detected_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    "detail" TEXT NOT NULL,
    "baseline" INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS "new_listings" (
    "market" TEXT NOT NULL DEFAULT 'NSE',
    "symbol" TEXT NOT NULL,
    "company" TEXT,
    "isin" TEXT,
    "series" TEXT,
    "listed_on" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "sessions" INTEGER,
    "sessions_required" INTEGER NOT NULL,
    "first_session" TEXT,
    "first_close" REAL,
    "last_session" TEXT,
    "last_close" REAL,
    "change_since_first_pct" REAL,
    "avg_turnover_20d" REAL,
    "median_turnover_20d" REAL,
    "turnover_floor" REAL NOT NULL,
    "market_cap" REAL,
    "updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    "logo_domain" TEXT,
    PRIMARY KEY ("market", "symbol")
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS "quarterly_filings" (
    "market" TEXT NOT NULL DEFAULT 'NSE',
    "symbol" TEXT NOT NULL,
    "period_end" TEXT NOT NULL,
    "is_consolidated" INTEGER NOT NULL,
    "seq_id" TEXT NOT NULL,
    "filed_at" TEXT NOT NULL,
    "broadcast_at" TEXT,
    "taxonomy" TEXT NOT NULL,
    "document_url" TEXT NOT NULL,
    "lines" TEXT NOT NULL,
    "parser_version" INTEGER NOT NULL,
    "parsed_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    "viewer_url" TEXT,
    "company" TEXT,
    PRIMARY KEY ("market", "symbol", "period_end", "is_consolidated")
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS "screener_runs" (
    "run_date" TEXT NOT NULL,
    "generated_at_utc" TEXT NOT NULL,
    "model_version" TEXT,
    "recommendation_policy_version" TEXT,
    "output_schema_version" TEXT,
    "model_validation_status" TEXT,
    "config_sha256" TEXT,
    "git_sha" TEXT,
    "git_dirty" INTEGER,
    "market_calendar_version" TEXT,
    "price_bar_as_of" TEXT,
    "analysis_as_of" TEXT,
    "row_count" INTEGER NOT NULL DEFAULT 0,
    "universe_selected_count" INTEGER,
    "technical_requested_count" INTEGER,
    "technical_collected_count" INTEGER,
    "technical_failed_count" INTEGER,
    "fundamental_missing_count" INTEGER,
    "strong_buy_count" INTEGER NOT NULL DEFAULT 0,
    "buy_count" INTEGER NOT NULL DEFAULT 0,
    "hold_count" INTEGER NOT NULL DEFAULT 0,
    "reduce_count" INTEGER NOT NULL DEFAULT 0,
    "sell_count" INTEGER NOT NULL DEFAULT 0,
    "manifest" TEXT,
    "ingested_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    "sectors" TEXT,
    "factor_model_applied" INTEGER,
    "market" TEXT NOT NULL DEFAULT 'NSE',
    PRIMARY KEY ("run_date", "market")
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS "universe_index" (
    "market" TEXT NOT NULL DEFAULT 'NSE',
    "observed_on" TEXT NOT NULL,
    "ew_return_pct" REAL NOT NULL,
    "members" INTEGER NOT NULL,
    "source" TEXT NOT NULL,
    PRIMARY KEY ("market", "observed_on")
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS "upcoming_events" (
    "market" TEXT NOT NULL,
    "symbol" TEXT NOT NULL,
    "company" TEXT,
    "next_result_date" TEXT,
    "result_purpose" TEXT,
    "next_call_at" TEXT,
    "next_call_date" TEXT,
    "call_source_url" TEXT,
    "updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    PRIMARY KEY ("market", "symbol")
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS "valuation_basis" (
    "market" TEXT NOT NULL DEFAULT 'NSE',
    "symbol" TEXT NOT NULL,
    "shares_outstanding" REAL,
    "net_profit_ttm" REAL,
    "book_equity" REAL,
    "ebitda_ttm" REAL,
    "revenue_ttm" REAL,
    "total_debt" REAL,
    "total_cash" REAL,
    "dividend_per_share" REAL,
    "period_end" TEXT,
    "statement_basis" TEXT,
    "source" TEXT,
    "run_date" TEXT,
    "updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    PRIMARY KEY ("market", "symbol")
) WITHOUT ROWID;
